class TreeNode {
  constructor(public left: TreeNode | null, public right: TreeNode | null) {}
}

function bottomUpTree(depth: number): TreeNode {
  if (depth === 0) {
    return new TreeNode(null, null);
  }

  const nextDepth = depth - 1;
  return new TreeNode(bottomUpTree(nextDepth), bottomUpTree(nextDepth));
}

function itemCheck(node: TreeNode): number {
  const left = node.left;
  if (left === null) {
    return 1;
  }

  return 1 + itemCheck(left) + itemCheck(node.right as TreeNode);
}

const proc = (globalThis as any).process;
const n = parseInt(proc.argv[2], 10);

const minDepth = 4;
const maxDepth = Math.max(minDepth + 2, n);
const stretchDepth = maxDepth + 1;

const output: string[] = [];

output.push(
  `stretch tree of depth ${stretchDepth}\t check: ${itemCheck(bottomUpTree(stretchDepth))}`
);

const longLivedTree = bottomUpTree(maxDepth);

for (let depth = minDepth; depth <= maxDepth; depth += 2) {
  const iterations = Math.pow(2, maxDepth - depth + minDepth);
  let check = 0;

  for (let i = 0; i < iterations; i++) {
    check += itemCheck(bottomUpTree(depth));
  }

  output.push(`${iterations}\t trees of depth ${depth}\t check: ${check}`);
}

output.push(
  `long lived tree of depth ${maxDepth}\t check: ${itemCheck(longLivedTree)}`
);

proc.stdout.write(output.join("\n") + "\n");
