declare const require: any;
declare const process: any;
declare const __filename: string;

const { Worker, isMainThread, parentPort, workerData } = require("worker_threads");
const os = require("os");

function factorials(n: number): number[] {
  const f = new Array<number>(n + 1);
  f[0] = 1;
  for (let i = 1; i <= n; i++) f[i] = f[i - 1] * i;
  return f;
}

function firstPermutation(n: number, index: number, fact: number[], perm: number[], count: number[], tmp: number[]): void {
  for (let i = 0; i < n; i++) {
    perm[i] = i;
    count[i] = 0;
  }

  let idx = index;
  for (let i = n - 1; i > 0; i--) {
    const d = Math.floor(idx / fact[i]);
    idx %= fact[i];
    count[i] = d;

    if (d !== 0) {
      for (let j = 0; j <= i; j++) tmp[j] = perm[j];
      const len = i + 1;
      for (let j = 0; j <= i; j++) perm[j] = tmp[(j + d) % len];
    }
  }
}

function computeRange(n: number, start: number, end: number): { checksum: number; maxFlips: number } {
  const fact = factorials(n);
  const perm = new Array<number>(n);
  const count = new Array<number>(n);
  const tmp = new Array<number>(n);
  const flipPerm = new Array<number>(n);

  firstPermutation(n, start, fact, perm, count, tmp);

  let checksum = 0;
  let maxFlips = 0;
  let sign = (start & 1) === 0 ? 1 : -1;
  let idx = start;

  while (idx < end) {
    const first = perm[0];

    if (first !== 0) {
      let flips = 1;
      let k = first;

      if (perm[k] !== 0) {
        for (let i = 0; i < n; i++) flipPerm[i] = perm[i];

        do {
          const next = flipPerm[k];
          flipPerm[k] = k;

          let lo = 1;
          let hi = k - 1;
          while (lo < hi) {
            const t = flipPerm[lo];
            flipPerm[lo++] = flipPerm[hi];
            flipPerm[hi--] = t;
          }

          flips++;
          k = next;
        } while (flipPerm[k] !== 0);
      }

      checksum += sign * flips;
      if (flips > maxFlips) maxFlips = flips;
    }

    idx++;
    sign = -sign;
    if (idx >= end) break;

    let r = 1;
    while (r < n) {
      const p0 = perm[0];
      for (let i = 0; i < r; i++) perm[i] = perm[i + 1];
      perm[r] = p0;

      count[r]++;
      if (count[r] <= r) break;
      count[r] = 0;
      r++;
    }
  }

  return { checksum, maxFlips };
}

async function main(): Promise<void> {
  const n = parseInt(process.argv[2], 10);
  const fact = factorials(n);
  const total = fact[n];

  let workers = 1;
  try {
    workers = Math.max(1, os.cpus().length | 0);
  } catch {
    workers = 1;
  }

  workers = Math.min(workers, 16, total);

  if (n < 10 || workers <= 1) {
    const result = computeRange(n, 0, total);
    process.stdout.write(
      String(result.checksum) + "\n" +
      "Pfannkuchen(" + n + ") = " + result.maxFlips + "\n"
    );
    return;
  }

  const promises: Promise<{ checksum: number; maxFlips: number }>[] = [];

  for (let i = 0; i < workers; i++) {
    const start = Math.floor((total * i) / workers);
    const end = Math.floor((total * (i + 1)) / workers);

    promises.push(new Promise((resolve, reject) => {
      const worker = new Worker(__filename, {
        workerData: { n, start, end }
      });

      let done = false;

      worker.on("message", (msg: { checksum: number; maxFlips: number }) => {
        done = true;
        resolve(msg);
      });

      worker.on("error", reject);

      worker.on("exit", (code: number) => {
        if (!done && code !== 0) reject(new Error("Worker stopped with exit code " + code));
      });
    }));
  }

  const results = await Promise.all(promises);

  let checksum = 0;
  let maxFlips = 0;

  for (const r of results) {
    checksum += r.checksum;
    if (r.maxFlips > maxFlips) maxFlips = r.maxFlips;
  }

  process.stdout.write(
    String(checksum) + "\n" +
    "Pfannkuchen(" + n + ") = " + maxFlips + "\n"
  );
}

if (isMainThread) {
  main();
} else {
  const n = workerData.n | 0;
  const start = workerData.start;
  const end = workerData.end;
  parentPort.postMessage(computeRange(n, start, end));
}
