const n = Number.parseInt(process.argv[2], 10);

const LINE_LEN = 60;
const OUT_CAP = 1 << 20;

const IM = 139968;
const IA = 3877;
const IC = 29573;

const SHIFT = 18;
const MASK = (1 << SHIFT) - 1;

let seed = 42;

const outBuf = Buffer.allocUnsafe(OUT_CAP);
let outPos = 0;

function flush(): void {
  let off = 0;
  while (off < outPos) {
    off += writeSync(1, outBuf, off, outPos - off);
  }
  outPos = 0;
}

function emitString(s: string): void {
  if (outPos + s.length > OUT_CAP) flush();
  outBuf.write(s, outPos, s.length, "ascii");
  outPos += s.length;
}

function makeTransition(chars: string, probs: number[]): Int32Array {
  const codes = new Uint8Array(chars.length);
  for (let i = 0; i < chars.length; i++) {
    codes[i] = chars.charCodeAt(i);
  }

  const lookup = new Uint8Array(IM);
  let idx = 0;
  let cumulative = probs[0];

  for (let i = 0; i < IM; i++) {
    const r = i / IM;
    while (cumulative <= r && idx < probs.length - 1) {
      idx++;
      cumulative += probs[idx];
    }
    lookup[i] = codes[idx];
  }

  const transition = new Int32Array(IM);
  for (let s = 0; s < IM; s++) {
    const next = (s * IA + IC) % IM;
    transition[s] = next | (lookup[next] << SHIFT);
  }

  return transition;
}

function emitRepeatedAlu(total: number): void {
