    "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";

  const aluBuf = Buffer.from(alu, "ascii");
  const aluLen = aluBuf.length;

  let remaining = total;
  let aluIdx = 0;
  let pos = outPos;

