      v = transition[localSeed];
      localSeed = v & MASK;
      outBuf[pos++] = v >>> SHIFT;

      v = transition[localSeed];
      localSeed = v & MASK;
      outBuf[pos++] = v >>> SHIFT;

      v = transition[localSeed];
      localSeed = v & MASK;
      outBuf[pos++] = v >>> SHIFT;

      v = transition[localSeed];
      localSeed = v & MASK;
      outBuf[pos++] = v >>> SHIFT;

      j -= 4;
