    while (j-- > 0) {
      v = transition[localSeed];
      localSeed = v & MASK;
      outBuf[pos++] = v >>> SHIFT;
    }

    outBuf[pos++] = 10;
    remaining -= lineLen;
  }

  seed = localSeed;
  outPos = pos;
