    if (b3 >= 97 && b3 <= 122) b3 -= 32;
    if (b4 >= 97 && b4 <= 122) b4 -= 32;

    if (b1 === pat1 && b2 === pat2 && b3 === pat3 && b4 === pat4) {
      return true;
    }
  }
  return false;
}

let sectionStart = -1;
let sectionEnd = dataLen;

