  for (let i = 0; i < s.length; i++) {
    const ch = s.charCodeAt(i);
    let c = 0;
    if (ch === 67) c = 1;
    else if (ch === 71) c = 2;
    else if (ch === 84) c = 3;
    v = v * 4 + c;
