  r3 = ((r3 << 2) | code) & 63;
  r4 = ((r4 << 2) | code) & 255;
  r6 = ((r6 << 2) | code) & 4095;
  r12 = ((r12 << 2) | code) & 16777215;

  r18 = r18 * 4 + code;
