import { Worker, isMainThread, parentPort, workerData } from "worker_threads";
import * as os from "os";

const MODE_A = 0;
const MODE_AT = 1;
const ITERATIONS = 10;

type TaskMessage = {
  mode: number;
  input: SharedArrayBuffer;
  output: SharedArrayBuffer;
};

function multiplyA(n: number, input: Float64Array, output: Float64Array): void {
  for (let i = 0; i < n; i++) {
    let sum = 0.0;
    let denom = (i * (i + 1)) / 2 + i + 1;
    let inc = i + 1;

    for (let j = 0; j < n; j++) {
      sum += input[j] / denom;
      denom += inc;
      inc += 1;
    }

    output[i] = sum;
  }
}

function multiplyAt(n: number, input: Float64Array, output: Float64Array): void {
  for (let i = 0; i < n; i++) {
    let sum = 0.0;
    let denom = (i * (i + 1)) / 2 + 1;
    let inc = i + 2;

    for (let j = 0; j < n; j++) {
      sum += input[j] / denom;
      denom += inc;
      inc += 1;
    }

    output[i] = sum;
  }
}

function multiplyARange(
  n: number,
  start: number,
  end: number,
  input: Float64Array,
  output: Float64Array
): void {
  for (let i = start; i < end; i++) {
    let sum = 0.0;
    let denom = (i * (i + 1)) / 2 + i + 1;
    let inc = i + 1;

    for (let j = 0; j < n; j++) {
      sum += input[j] / denom;
      denom += inc;
      inc += 1;
    }

    output[i] = sum;
  }
}

function multiplyAtRange(
  n: number,
  start: number,
  end: number,
  input: Float64Array,
  output: Float64Array
): void {
  for (let i = start; i < end; i++) {
    let sum = 0.0;
    let denom = (i * (i + 1)) / 2 + 1;
    let inc = i + 2;

    for (let j = 0; j < n; j++) {
      sum += input[j] / denom;
      denom += inc;
      inc += 1;
    }

    output[i] = sum;
  }
}

if (!isMainThread) {
  const n: number = workerData.n;
  const start: number = workerData.start;
  const end: number = workerData.end;

  parentPort!.on("message", (msg: TaskMessage) => {
    const input = new Float64Array(msg.input);
    const output = new Float64Array(msg.output);

    if (msg.mode === MODE_A) {
      multiplyARange(n, start, end, input, output);
    } else {
      multiplyAtRange(n, start, end, input, output);
    }

    parentPort!.postMessage(0);
  });
} else {
  async function main(): Promise<void> {
    const n = parseInt(process.argv[2], 10);

    const uBuffer = new SharedArrayBuffer(n * Float64Array.BYTES_PER_ELEMENT);
    const vBuffer = new SharedArrayBuffer(n * Float64Array.BYTES_PER_ELEMENT);
    const tmpBuffer = new SharedArrayBuffer(n * Float64Array.BYTES_PER_ELEMENT);

    const u = new Float64Array(uBuffer);
    const v = new Float64Array(vBuffer);
    const tmp = new Float64Array(tmpBuffer);

    u.fill(1.0);

    const available =
      Number((os as any).availableParallelism?.() ?? os.cpus().length) || 1;
    const workerCount = n >= 200 ? Math.min(available, 16, n) : 1;

    if (workerCount <= 1) {
      for (let i = 0; i < ITERATIONS; i++) {
        multiplyA(n, u, tmp);
        multiplyAt(n, tmp, v);
        multiplyA(n, v, tmp);
        multiplyAt(n, tmp, u);
      }
    } else {
      const workers: Worker[] = [];

      let pending = 0;
      let resolveCurrent: (() => void) | null = null;

      for (let i = 0; i < workerCount; i++) {
        const start = Math.floor((n * i) / workerCount);
        const end = Math.floor((n * (i + 1)) / workerCount);

        const worker = new Worker(__filename, {
          workerData: { n, start, end },
        });

        worker.on("message", () => {
          pending--;
          if (pending === 0 && resolveCurrent !== null) {
            const resolve = resolveCurrent;
            resolveCurrent = null;
            resolve();
          }
        });

        workers.push(worker);
      }

      const runPass = (
        mode: number,
        input: SharedArrayBuffer,
        output: SharedArrayBuffer
      ): Promise<void> => {
        return new Promise<void>((resolve) => {
          pending = workers.length;
          resolveCurrent = resolve;

          for (let i = 0; i < workers.length; i++) {
            workers[i].postMessage({ mode, input, output });
          }
        });
      };

      for (let i = 0; i < ITERATIONS; i++) {
        await runPass(MODE_A, uBuffer, tmpBuffer);
        await runPass(MODE_AT, tmpBuffer, vBuffer);
        await runPass(MODE_A, vBuffer, tmpBuffer);
        await runPass(MODE_AT, tmpBuffer, uBuffer);
      }

      for (let i = 0; i < workers.length; i++) {
        workers[i].terminate();
      }
    }

    let vBv = 0.0;
    let vv = 0.0;

    for (let i = 0; i < n; i++) {
      vBv += u[i] * v[i];
      vv += v[i] * v[i];
    }

    process.stdout.write(Math.sqrt(vBv / vv).toFixed(9) + "\n");
  }

