for (let x = 0; x < n; x++) {
  const cr = x * scale - 1.5;
  const cmq = cr - 0.25;
  const cpo = cr + 1.0;

  crs[x] = cr;
  crMinusQuarter[x] = cmq;
  crMinusQuarterSq[x] = cmq * cmq;
  crPlusOneSq[x] = cpo * cpo;
}

const maxComputedY: number = Math.floor(n / 2);

for (let y = 0; y <= maxComputedY; y++) {
  const ci: number = y * scale - 1.0;
  const ci2: number = ci * ci;
  const rowOffset: number = headerLength + y * rowBytes;

  let outIndex = rowOffset;
  let x = 0;

  if (ci2 <= 0.421875) {
    const quarterCi2 = 0.25 * ci2;

    for (let xb = 0; xb < rowBytes; xb++) {
      let byte = 0;
      let bit = 0x80;

      for (let k = 0; k < 8 && x < n; k++, x++, bit >>= 1) {
        if (crPlusOneSq[x] + ci2 <= 0.0625) {
          byte |= bit;
          continue;
        }

